#做梦素材 #创作者扶持计划 #重温经典老剧

3 篇资料
应该还有更多那时候放的电视剧了，古装的、仙侠的。
90 年代到 2000 年代初的古装、仙侠剧里，“正义叙事” 确实是绝对主流，再补充几部标志性的：
《包青天》（93 版）：金超群饰演的包拯，额头月牙就是 “正义符号”，每集都在 “铡恶官、护百姓”，“王子犯法与庶民同罪” 的台词刻进 DNA，连反派都在明面上坏，从没有 “灰色地带” 的模糊。
《铁齿铜牙纪晓岚》：和珅代表的 “权钱腐败” 和纪晓岚代表的 “清流坚守” 形成极致对立，哪怕用喜剧包装，核心也是 “正义靠智慧和勇气对抗强权”，最后总能让和珅吃瘪，给观众 “恶有恶报” 的爽感。
《仙剑奇侠传一》：看似是仙侠爱情，内核藏着 “小人物担大义”—— 李逍遥从市井小混混成长为对抗拜月教的英雄，赵灵儿为苍生牺牲，哪怕有遗憾，“守护正义、对抗邪恶” 的主线从未动摇，连反派拜月的 “极端理念” 都被明确否定。
《射雕英雄传》（03 版 / 83 版）：武侠里的 “正义教科书”，郭靖的 “侠之大者，为国为民” 是终极价值观，杨康因 “认贼作父” 走向毁灭，善恶有清晰的边界，努力践行正义的人终会被认可（哪怕笨如郭靖）。
《大宋提刑官》：宋慈的 “法医破案” 看似冷静，实则每桩案件都在撕开官场黑幕，哪怕最后他烧了案卷、理想受挫，过程中 “追求真相、不向权力低头” 的执着，依然在传递 “正义虽难，必须坚守” 的信念。
这些剧的共同点是：正义有具体的模样（清官、侠客、少年英雄），邪恶有明确的下场（被惩罚、被唾弃），哪怕过程曲折，“正义必胜” 的结局从不让人怀疑。这种 “非黑即白” 的坚定，恰恰是后来现实中 “模糊地带” 增多后，94-96 这批人最怀念的东西。
